entries[65637] = { ["name"] = "Großer roter Elekk", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren großen roten Elekk oder gibt ihn wieder frei.\n\"Die ersten roten Elekkkälber wurden in Azeroth nach der Ankunft der Exodar geboren und wurden nie in Nagrand gesichtet. Einige Züchter sind der Ansicht, dass die einzigartige Färbung derselben Strahlung entspringt, die auch die Blutmythosinsel verwüstet hat.\"\nVerkäufer:\nIrisee\nZone:\nEiskrone\nKosten:\n500" }
entries[65638] = { ["name"] = "Schneller Mondsäbler", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren schnellen Mondsäbler oder gibt ihn wieder frei.\n\"Viele Nachtelfen verehren diese stolzen Reittiere, da deren schimmernde Felle für sie Elune, die Göttin des Mondes, symbolisieren.\"\nVerkäufer:\nRook Falkenfaust\nZone:\nEiskrone\nKosten:\n500" }
entries[65639] = { ["name"] = "Schneller roter Falkenschreiter", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren schnellen roten Falkenschreiter oder gibt ihn wieder frei.\n\"Was soll das heißen, \"Das ist doch Tönung\"? Oh, Ihr meint den Vogel. Ja, wir haben die rote Farbe ein wenig aufgefrischt. - Trellis Morgensonne\"\nVerkäufer:\nTrellis Morgensonne\nZone:\nEiskrone\nKosten:\n500" }
entries[65640] = { ["name"] = "Schnelles graues Ross", ["text"] = "Wirken in 1.5 sek.\nBeschwört ein reitbares schnelles graues Ross oder gibt es wieder frei.\n\"Ein Veteran der härtesten Schlachten des Argentumkreuzzugs.\"\nVerkäufer:\nKorporal Arthur Flew\nZone:\nEiskrone\nKosten:\n500" }
entries[65641] = { ["name"] = "Großer goldener Kodo", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren großen goldenen Kodo oder gibt ihn wieder frei.\n\"Als Alpha seiner Herde ist dieser Kodo ein Paradebeispiel für diese mächtigen Kreaturen, die durch das Südliche Brachland donnern.\"\nVerkäufer:\nDoru Donnerhorn\nZone:\nEiskrone\nKosten:\n500" }
entries[65642] = { ["name"] = "Turboschreiter", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren Turboschreiter oder gibt ihn wieder frei.\n\"Der Spiegel ist nicht dazu da, damit Ihr zurückblicken könnt, sondern damit Eure Feinde noch etwas anderes als Euren Auspuff zu sehen bekommen. - Rillie Spindelnuss\"\nVerkäufer:\nRillie Spindelnuss\nZone:\nEiskrone\nKosten:\n500" }
entries[65643] = { ["name"] = "Schneller violetter Widder", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren schnellen violetten Widder oder gibt ihn wieder frei.\n\"Der dicke Schädel und die riesigen Hörner des Barak-Tor'ol-Widders machen ihn zum perfekten Reittier, um durch Gruppen gepanzerter Gegner zu rasen.\"\nVerkäufer:\nDerrick Scheckenbart\nZone:\nEiskrone\nKosten:\n500" }
entries[65644] = { ["name"] = "Schneller purpurfarbener Raptor", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren schnellen purpurfarbenen Raptor oder gibt ihn wieder frei.\n\"Diese Dschungeljäger sind schon lange mit den Trollen verbündet und haben eine enge Bindung zu ihren Herren aufgebaut. Sie sind zum Reittier, Beschützer und Freund geworden.\"\nVerkäufer:\nSamamba\nZone:\nEiskrone\nKosten:\n500" }
entries[65645] = { ["name"] = "Weißes Skelettschlachtross", ["text"] = "Wirken in 1.5 sek.\nBeschwört ein weißes Skelettschlachtross oder gibt es wieder frei.\n\"Wenn gefallene Helden in den Untod erweckt werden, folgen ihnen auch ihre Pferde.\"\nVerkäufer:\nEliza Killian\nZone:\nEiskrone\nKosten:\n500" }
entries[65646] = { ["name"] = "Schneller burgundfarbener Wolf", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren schnellen burgundfarbenen Wolf oder gibt ihn wieder frei.\n\"Mit den Wölfen der Horde kann man sich nur anfreunden, man kann sie nicht zähmen.\"\nVerkäufer:\nFreka Blutaxt\nZone:\nEiskrone\nKosten:\n500" }
