entries[65797] = { ["name"] = "Sternenregen", ["text"] = "40 Meter Reichweite\nSofort\nBeschwört einen Wirbel aus Sternen vom Himmel auf alle Ziele im Umkreis von 30 Metern um den Zaubernden herab, von denen jeder allen Feinden im Umkreis von 5 Metern um das feindliche Ziel 55 Arkanschaden zufügt. Hält 8 Sek. lang an." }
entries[65798] = { ["name"] = "Sternenregen", ["text"] = "Kanalisiert (Wirken in 8 sek.) 30 sek. Abklingzeit\nBeschwört einen Wirbel aus Sternen vom Himmel auf alle Ziele im Umkreis von 30 Metern um den Zaubernden herab, von denen jeder allen Feinden im Umkreis von 5 Metern um das feindliche Ziel 55 Arkanschaden zufügt. Hält 8 Sek. lang an." }
