entries[65800] = { ["name"] = "Arkane Explosion", ["text"] = "22% von Grundmana\nSofort\nVerursacht eine Explosion arkaner Magie um den Zaubernden herum und fügt allen Zielen in einem Umkreis von 10 Metern 24 Arkanschaden zu." }
entries[65801] = { ["name"] = "Verwandlung", ["text"] = "7% von Grundmana 30 Meter Reichweite\nWirken in 1.5 sek. 15 sek. Abklingzeit\nVerwandelt den Feind in ein Schaf und zwingt ihn, 10 Sek. lang so herumzuwandern. Während das Schaf herumwandert, kann es weder angreifen noch Zauber wirken. Jeglicher erlittene Schaden verwandelt das Ziel in seine normale Gestalt zurück. Es kann immer nur jeweils ein Ziel verwandelt werden. Wirkt nur bei Wildtieren, Humanoiden und Tieren." }
entries[65802] = { ["name"] = "Eisblock", ["text"] = "15 Mana\nSofort 5 min Abklingzeit\nIhr werdet in einen Eisblock eingehüllt, der Euch 5 Sek. lang vor allen körperlichen Angriffen und Zaubern schützt, allerdings könnt Ihr während dieser Zeit weder angreifen noch Euch bewegen und auch keine Zauber wirken. Verursacht ebenfalls 'Unterkühlung' und verhindert 30 Sek. lang, dass 'Eisblock' gewirkt werden kann." }
