entries[65808] = { ["name"] = "Entfesselte Nacht", ["text"] = "Unbegrenzte Reichweite\nSofort\nDie konzentrierte Nacht entfesselt ihre Energien und fügt Gegnern innerhalb von 6 Metern 64 Nachtschaden zu." }
entries[65809] = { ["name"] = "Furcht", ["text"] = "12% von Grundmana 20 Meter Reichweite\nWirken in 1.5 sek. 8 sek. Abklingzeit\nErfüllt den Feind mit Furcht, woraufhin er bis zu 10 Sek. lang voller Furcht flüchtet. Erlittener Schaden kann den Effekt unterbrechen. Es kann immer nur jeweils ein einzelnes Ziel mit Furcht erfüllt werden." }
entries[65810] = { ["name"] = "Verderbnis", ["text"] = "14% von Grundmana 30 Meter Reichweite\nSofort\nVerderbt das Ziel und verursacht 18 Sek. lang insgesamt 143 Schattenschaden." }
