entries[65934] = { ["name"] = "Gegenschlag", ["text"] = "Nahkampfreichweite\nSofort\nEin sofortiger Gegenangriff gegen jeden Feind, der Euch im Nahkampf schlägt. Hält 12 Sek. lang an. Bei Nahkampfangriffen, die von hinten geführt werden, ist ein Gegenangriff nicht möglich. Maximal 20 Angriffe können 'Gegenschlag' auslösen." }
