entries[65936] = { ["name"] = "Rüstung zerreißen", ["text"] = "Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nZerreißt die Rüstung des Ziels, verringert sie pro Einsatz von 'Rüstung zerreißen' um 4% und verursacht ein hohes Maß an Bedrohung. Die Bedrohung wird durch Angriffskraft erhöht. Kann bis zu 5-mal angewendet werden. Hält 20 Sek. lang an." }
