entries[65940] = { ["name"] = "Zerschmetternder Wurf", ["text"] = "30 Meter ReichweiteWirken in 1.5 sek. 5 min Abklingzeit\nBenötigt Nahkampfwaffe\nWirft Eure Waffe nach dem Feind, verursacht Waffenschaden, verringert die Rüstung des Ziels 10 Sek. lang um 0% oder entfernt jegliche Unverwundbarkeitseffekte." }
