entries[65946] = { ["name"] = "Klingensturm", ["text"] = "Sofort\nBenötigt Nahkampfwaffe\nIn einem stählernen Wirbel greift Ihr Feinde in einem Umkreis von 8 Metern an und verursacht 50% Waffenschaden." }
entries[65947] = { ["name"] = "Klingensturm", ["text"] = "Sofort 1.5 min Abklingzeit\nBenötigt Nahkampfwaffe\nFührt sofort einen Wirbelangriff aus, der alle Ziele in der Nähe trifft, sowie innerhalb der nächsten 8 Sek. alle 1 Sek. weitere Wirbelangriffe. Während Ihr von den Effekten von 'Klingensturm' betroffen seid, könnt Ihr Euch bewegen, aber keine anderen Aktionen ausführen. Ihr fühlt weder Mitleid, noch Bedauern oder Furcht und es gibt keine Möglichkeit, Euch aufzuhalten, es sei denn, Ihr werdet getötet." }
entries[65949] = { ["name"] = "Schnelligkeit der Val'kyr", ["text"] = "Sofort\nDie Macht der Zwillinge erhöht 15 Sek. lang das Angriffstempo um 10%. Stapelbar." }
entries[65950] = { ["name"] = "Berührung des Lichts", ["text"] = "Unbegrenzte Reichweite\nSofort\nDie Val'kyr hat Euch mit ihrer Berührung des Lichts belegt, die Spielern, die unter dem Effekt der Essenz der Nacht stehen, alle 2 Sek. 1119 Lichtschaden zufügt. Die Berührung des Lichts wird helle Ziele nicht verletzen." }
entries[65951] = { ["name"] = "Heckenschützenschuss", ["text"] = "1000 Meter Reichweite\nSofort\nEin Schuss, ein Treffer." }
entries[65953] = { ["name"] = "Summon Gilnean Bloodhound" }
entries[65954] = { ["name"] = "Blutsturz", ["text"] = "35 Energie Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nEin sofortiger Stoß, der 110% Waffenschaden sowie einen Blutsturz beim Ziel verursacht und so den dem Ziel zugefügten körperlichen Schaden um bis zu 14 erhöht. Hält 10 Aufladungen oder 15 Sek. lang an. Gewährt 1 Combopunkt." }
entries[65955] = { ["name"] = "Dolchfächer", ["text"] = "30 Energie\nSofort 2 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nWirft sofort beide Waffen auf alle Ziele innerhalb von 10 Metern und verursacht 90% Waffenschaden." }
entries[65956] = { ["name"] = "Klingenwirbel", ["text"] = "Sofort 2 min Abklingzeit\nErhöht Euer Angriffstempo um 20%. Zusätzlich treffen Angriffe einen weiteren in der Nähe befindlichen Gegner. Hält 15 Sek. an.\n(100ms Abklingzeit)" }
entries[65957] = { ["name"] = "Ausweiden", ["text"] = "35 Energie Nahkampfreichweite\nSofort 10 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nFinishing-Move, der 1679 körperlichen Schaden verursacht." }
entries[65960] = { ["name"] = "Blenden", ["text"] = "30 Energie 20 Meter Reichweite\nSofort 2 min Abklingzeit\nBlendet das Ziel und lässt es bis zu 1 Min. lang desorientiert umherlaufen. Jeglicher erlittene Schaden wird den Effekt aufheben." }
entries[65961] = { ["name"] = "Mantel der Schatten", ["text"] = "Sofort 1.5 min Abklingzeit\nBannt sofort alle schädlichen Zaubereffekte und erhöht Eure Chance, jeder Art von Zauber zu widerstehen, 5 Sek. lang um 90%. Effekte, welche die Benutzung von 'Mantel der Schatten' verhindern, werden nicht entfernt." }
entries[65962] = { ["name"] = "Wundgift", ["text"] = "Nahkampfreichweite\nSofort\nVergiftet den Gegner und verringert alle auf ihn angewandten Heileffekte 15 Sek. lang um 50%." }
