entries[65970] = { ["name"] = "Sturmschlag", ["text"] = "8% von Grundmana Nahkampfreichweite\nSofort 8 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nGreift das Ziel sofort mit beiden Waffen an. Zusätzlich werden die nächsten 4 Quellen des Naturschadens, der dem Ziel zugefügt wird, um 20% erhöht. Hält 12 Sek. lang an." }
entries[65971] = { ["name"] = "Sturmschlag", ["text"] = "Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nGreift das Ziel sofort mit beiden Waffen an. Zusätzlich wird der dem Ziel zugefügte Naturschaden um 0% erhöht. Hält bis Abbruch lang an." }
entries[65972] = { ["name"] = "Sturmschlag", ["text"] = "Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nGreift das Ziel sofort mit beiden Waffen an. Zusätzlich wird der dem Ziel zugefügte Naturschaden um 0% erhöht. Hält bis Abbruch lang an." }
entries[65973] = { ["name"] = "Erdschock", ["text"] = "18% von Grundmana 25 Meter Reichweite\nSofort 6 sek. Abklingzeit\nSchockt das Ziel unmittelbar mit erschütternder Kraft und verursacht 554 Naturschaden. Unterbricht außerdem das Wirken von Zaubern und verhindert 2 Sek. lang, dass diese Art Zauber gewirkt werden kann." }
entries[65974] = { ["name"] = "Lavapeitsche", ["text"] = "4% von Grundmana Nahkampfreichweite\nSofort 6 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nLädt Eure Schildhandwaffe mit Lava auf, verursacht sofort 100% Waffenschaden der Schildhandwaffe. Der Schaden ist um 25% erhöht, wenn Eure Schildhandwaffe mit 'Flammenzunge' verzaubert ist." }
