entries[65980] = { ["name"] = "Kampfrausch", ["text"] = "750 Mana 20 Meter Reichweite\nSofort 10 min Abklingzeit\nErhöht Nahkampf-, Distanzangriffs- und Zaubertempo aller Gruppenmitglieder um 30%. Hält 40 Sek. lang an." }
