entries[65986] = { ["name"] = "Waffe des Mahlstroms", ["text"] = "Sofort\nVerringert die Zauberzeit Eures nächsten Wirkens von 'Blitzschlag', 'Kettenblitzschlag', 'Geringe Welle der Heilung', 'Welle der Heilung' oder 'Kettenheilung' um 20%." }
