entries[65988] = { ["name"] = "Waffe des Mahlstroms", ["text"] = "Wenn Ihr mit einer Nahkampfwaffe Schaden verursacht, besteht eine Chance, dass die Zauberzeit Eures nächsten Wirkens von 'Blitzschlag', 'Kettenblitzschlag', 'Geringe Welle der Heilung', 'Kettenheilung' oder 'Welle der Heilung' um 1% verringert wird. Bis zu 5-mal stapelbar.\n(Procchance: 15%)" }
entries[65989] = { ["name"] = "Totem der Erdung", ["text"] = "5% von Grundmana\nSofort 15 sek. Abklingzeit\nBeschwört ein Totem der Erdung mit 5 Gesundheit zu Füßen des Zaubernden, das einen schädlichen Zauber, der auf ein in der Nähe befindliches Gruppenmitglied gewirkt wurde, auf das Totem umleitet und es zerstört. Zauber mit Flächenwirkung werden nicht umgeleitet. Hält 45 Sek. lang an." }
entries[65990] = { ["name"] = "Totem des Windzorns", ["text"] = "11% von Grundmana\nSofort\nBeschwört ein Totem des Windzorns mit 5 Gesundheit zu Füßen des Zaubernden. Das Totem erhöht das Nahkampfangriffstempo aller Gruppen- und Schlachtzugsmitglieder im Umkreis von 0 Metern um 5%. Hält 5 Min. lang an." }
entries[65991] = { ["name"] = "Totem der Erdstärke", ["text"] = "10% von Grundmana\nSofort\nBeschwört ein Totem der Erdstärke mit 5 Gesundheit zu Füßen des Zaubernden. Die Stärke und Beweglichkeit aller Gruppen- und Schlachtzugsmitglieder in einem Umkreis von 0 Metern wird um 5 erhöht. Hält 5 Min. lang an." }
entries[65992] = { ["name"] = "Totem des Erdstoßes", ["text"] = "2% von Grundmana\nSofort\nBeschwört ein Totem des Erdstoßes mit 5 Gesundheit zu Füßen des Zaubernden, das den Boden erschüttert und Furcht-, Schlaf- und Betörungseffekte von Gruppenmitgliedern im Umkreis von 30 Metern entfernt. Hält 5 Min. lang an." }
entries[65993] = { ["name"] = "Totem des heilenden Flusses", ["text"] = "30 Meter Reichweite\nSofort\nStellt bei nahen Verbündeten 96 Gesundheit wieder her." }
entries[65994] = { ["name"] = "Heilender Fluss", ["text"] = "Stellt alle 2 Sek. Gesundheit her." }
entries[65995] = { ["name"] = "Totem des heilenden Flusses", ["text"] = "3% von Grundmana\nSofort\nBeschwört ein Totem des heilenden Flusses mit 5 Gesundheit zu Füßen des Zaubernden. Gruppenmitglieder im Umkreis von 40 Metern erhalten alle 2 Sek. 96 Gesundheit. Hält 5 Min. lang an." }
