entries[66006] = { ["name"] = "Göttlicher Sturm", ["text"] = "12% von Grundmana\nSofort 10 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nEin sofortiger Waffenangriff, der bei bis zu 4 Feinden innerhalb von 8 Metern 110% Waffenschaden verursacht." }
