entries[66008] = { ["name"] = "Buße", ["text"] = "9% von Grundmana 20 Meter Reichweite\nSofort 1 min Abklingzeit\nVersetzt das gegnerische Ziel in einen meditativen Zustand, macht es so bis zu 10 Sek. lang handlungsunfähig. Jeglicher ihm zugefügte Schaden weckt das Ziel wieder auf. Wirkt auf Dämonen, Drachkin, Riesen, Humanoide und Untote." }
entries[66009] = { ["name"] = "Hand des Schutzes", ["text"] = "6% von Grundmana 30 Meter Reichweite\nSofort 5 min Abklingzeit\nEin anvisiertes Bündnismitglied ist 10 Sek. lang vor allen körperlichen Angriffen geschützt." }
entries[66010] = { ["name"] = "Gottesschild", ["text"] = "3% von Grundmana\nSofort 5 min Abklingzeit\nSchützt den Paladin 12 Sek. lang vor jeglichem Schaden und Zaubern, verringert jedoch seinen verursachten Schaden um 50%." }
entries[66011] = { ["name"] = "Zornige Vergeltung", ["text"] = "8% von Grundmana\nSofort 3 min Abklingzeit\nErhöht jeglichen verursachten Schaden und Heilung 20 Sek. lang um 20%." }
