entries[66013] = { ["name"] = "Durchdringende Kälte", ["text"] = "Sofort\nDurchdringende Kälte peinigt mehrere feindliche Ziele und verursacht alle 3 Sek. 1119 Frostschaden. Hält 18 Sek. lang an." }
