entries[66017] = { ["name"] = "Todesgriff", ["text"] = "30 Meter Reichweite\nSofort 20 sek. Abklingzeit\nNutzt die Mächte unheiliger Energien, die alle Materie umgibt und bindet, um das Ziel zum Todesritter hin zu ziehen und es zu zwingen, ihn bis Abbruch lang anzugreifen." }
entries[66018] = { ["name"] = "Strangulieren", ["text"] = "30 Meter Reichweite\nSofort 2 min Abklingzeit\nWürgt einen Feind und bringt ihn bis zu 5 Sek. lang zum Schweigen. Endet der Effekt, erleidet das Ziel 34 Schattenschaden." }
entries[66019] = { ["name"] = "Todesmantel", ["text"] = "30 Meter Reichweite\nSofort 5 sek. Abklingzeit\nEntfesselt unheilige Energien, die einem gegnerischen Ziel 1175 Schattenschaden zufügen oder ein verbündetes untotes Ziel um (1087 * 1.5) Gesundheit heilen." }
entries[66020] = { ["name"] = "Eisketten", ["text"] = "25 Meter Reichweite\nSofort 8 sek. Abklingzeit\nUmschlingt das Ziel mit eisigen Ketten und verringert seine Bewegungsgeschwindigkeit auf 5% des normalen Wertes. Das Ziel erhält im Verlauf von 10 Sek. pro Sekunde 10% seiner Bewegungsgeschwindigkeit zurück." }
entries[66021] = { ["name"] = "Eisige Berührung", ["text"] = "20 Meter Reichweite\nSofort 8 sek. Abklingzeit\nUnterkühlt das Ziel für 885 bis 961 Frostschaden und steckt es mit Frostfieber an, einer Krankheit, die regelmäßig Schaden verursacht und 24 Sek. lang das Nahkampf- und Distanzangriffstempo des Ziels um 0% verringert." }
