entries[66034] = { ["name"] = "Kandierte Süßkartoffel", ["text"] = "Wirken in 2 sek.\nReagenzien:\nSüßkartoffel aus Mulgore , Honig , Herbstliche Gewürze\nWeltereignis:\nPilgerfreudenfest\nWeltverkäufer:\nVerkäufer des Pilgerfreudenfests\nGegenstand:\nDas Beste zum Pilgerfreudenfest - DAS Kochbuch\nKosten:\n1\n\nBenutzen: Stellt im Verlauf von 20 Sek. Eure Gesundheit und Mana vollständig wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang Tempo.\nBenötigt Pilgerfreudenfest" }
entries[66035] = { ["name"] = "Moosbeerenchutney", ["text"] = "Wirken in 2 sek.\nReagenzien:\nSäuerliche Moosbeeren vom Südstrom , Honig\nWeltereignis:\nPilgerfreudenfest\nWeltverkäufer:\nVerkäufer des Pilgerfreudenfests\nGegenstand:\nDas Beste zum Pilgerfreudenfest - DAS Kochbuch\nKosten:\n1\n\n(0)\nBenutzen: Stellt im Verlauf von 20 Sek. Eure Gesundheit und Euer Mana vollständig wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang Vielseitigkeit.\nBenötigt Pilgerfreudenfest" }
entries[66036] = { ["name"] = "Kürbiskuchen", ["text"] = "Wirken in 2 sek.\nReagenzien:\nReifer Tirisfalkürbis , Honig\nWeltereignis:\nPilgerfreudenfest\nWeltverkäufer:\nVerkäufer des Pilgerfreudenfests\nGegenstand:\nDas Beste zum Pilgerfreudenfest - DAS Kochbuch\nKosten:\n1\n\nBenutzen: Stellt im Verlauf von 20 Sek. Eure Gesundheit und Euer Mana vollständig wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang kritischen Trefferwert.\nBenötigt Pilgerfreudenfest" }
entries[66037] = { ["name"] = "Langsam gerösteter Truthahn", ["text"] = "Wirken in 2 sek.\nReagenzien:\nWilder Truthahn , Honig (2), Herbstliche Gewürze\nWeltereignis:\nPilgerfreudenfest\nWeltverkäufer:\nVerkäufer des Pilgerfreudenfests\nGegenstand:\nDas Beste zum Pilgerfreudenfest - DAS Kochbuch\nKosten:\n1\n\nBenutzen: Stellt im Verlauf von 20 Sek. Eure Gesundheit und Euer Mana vollständig wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang Meisterschaft.\nBenötigt Pilgerfreudenfest" }
