entries[66087] = { ["name"] = "Hippogryph des Silberbunds", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren Hippogryphen des Silberbunds oder gibt ihn wieder frei. Das ist ein Flugreittier.\n\"Hippogryphen des Silberbunds sind ihren Reitern und der Allianz absolut treu ergeben.\"\nVerkäufer:\nHiren Lehrensang\nZone:\nEiskrone\nDer Silberbund - Ehrfürchtig\nKosten:\n150" }
entries[66088] = { ["name"] = "Drachenfalke der Sonnenhäscher", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren Drachenfalken der Sonnenhäscher oder gibt ihn wieder frei. Das ist ein Flugreittier.\n\"Die Sonnenhäscher von Dalaran erwählen nur die flinksten und beachtlichsten Drachenfalken als ihre Reittiere.\"\nVerkäufer:\nVasarin Morgenröte\nZone:\nEiskrone\nDie Sonnenhäscher - Ehrfürchtig\nKosten:\n150" }
entries[66090] = { ["name"] = "Streitross der Quel'dorei", ["text"] = "Wirken in 1.5 sek.\nBeschwört ein reitbares Streitross der Quel'dorei oder gibt es wieder frei.\n\"Stammt von einer Familie edler Pferde ab, die an den Ufern des Brunnens der Ewigkeit gegrast haben.\"\nVerkäufer:\nHiren Lehrensang\nZone:\nEiskrone\nDer Silberbund - Ehrfürchtig\nKosten:\n100" }
entries[66091] = { ["name"] = "Falkenschreiter der Sonnenhäscher", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren Falkenschreiter der Sonnenhäscher oder gibt ihn wieder frei.\n\"Ich erwarte Geschwindigkeit, Anmut und Disziplin auf dem Schlachtfeld. Das hier sollte meine Erwartungen erfüllen. - Eressea Morgensänger\"\nVerkäufer:\nVasarin Morgenröte\nZone:\nEiskrone\nDie Sonnenhäscher - Ehrfürchtig\nKosten:\n100" }
